'::jsonb;
  it jsonb;
  i int := 0;
  v_code text;
BEGIN
  IF v_shop::text = 'YOUR_SHOP_ID' THEN
    RAISE EXCEPTION 'Set v_shop to your shop id (select id, name from shops)';
  END IF;

  UPDATE menu_products SET active = false, updated_at = now() WHERE shop_id = v_shop;

  FOR it IN SELECT * FROM jsonb_array_elements(v_items) LOOP
    v_code := trim(it->>'id');
    INSERT INTO menu_products (shop_id, product_code, name_en, name_gu, price, keywords, sort_order, active, updated_at)
    VALUES (
      v_shop, v_code, it->>'nameEn', coalesce(it->>'nameGu',''),
      (it->>'price')::numeric,
      ARRAY(SELECT jsonb_array_elements_text(it->'keywords')),
      i, true, now()
    )
    ON CONFLICT (shop_id, product_code) DO UPDATE SET
      name_en = EXCLUDED.name_en,
      name_gu = EXCLUDED.name_gu,
      price = EXCLUDED.price,
      keywords = EXCLUDED.keywords,
      sort_order = EXCLUDED.sort_order,
      active = true,
      updated_at = now();
    i := i + 1;
  END LOOP;
  RAISE NOTICE 'Loaded % menu items for shop %', i, v_shop;
END $$;
